export type Usage = {
    object: string;
    emails: {
        /**
         * The last 24 hours. There is no daily cap, so limit and resets_at are null.
         */
        daily: {
            used: number;
            limit: number | null;
            sent: number;
            received: number;
            resets_at: string | null;
        };
        /**
         * This month. Received mail does not count, so used equals sent.
         */
        monthly: {
            used: number;
            limit: number;
            sent: number;
            received: number;
            resets_at: string;
        };
        credits: {
            /**
             * Prepaid credits
             */
            balance: number;
        };
        /**
         * What can still be sent before a send is refused: the monthly allowance left plus credits
         */
        effective_remaining: number;
    };
    contacts: {
        used: number;
        limit: number;
    };
    segments: {
        used: number;
        limit: number;
    };
    /**
     * Broadcasts queued, scheduled or sent this month
     */
    broadcasts: {
        used: number;
        limit: number;
    };
    /**
     * Not offered: always 0, with a null next_increase_at
     */
    ai_credits: {
        used: number;
        limit: number;
        next_increase_at: string | null;
    };
    /**
     * Not offered: always 0
     */
    automation_runs: {
        used: number;
        limit: number;
        resets_at: string;
    };
    /**
     * A null limit means no cap
     */
    domains: {
        used: number;
        limit: number | null;
    };
    /**
     * Per API key; null for a dashboard session
     */
    rate_limit: {
        /**
         * Requests allowed per duration
         */
        limit: number;
        duration: string;
    } | null;
};

