export type TemplateVariableWritable = {
    /**
     * Use it in the content as {{{KEY}}}. Letters, digits and underscores. FIRST_NAME, LAST_NAME, EMAIL, UNSUBSCRIBE_URL, RESEND_UNSUBSCRIBE_URL, contact and this are reserved.
     */
    key: string;
    type: 'string' | 'number';
    /**
     * Used when a send gives no value. Must match the type. Without one, every send must pass a value for this variable or it answers 422.
     */
    fallback_value?: string | number | null;
};

/**
 * Requires html, or markdown (an SMTPfast addition).
 */
export type CreateTemplateRequestWritable = {
    name: string;
    /**
     * A second handle, unique in the team, that works wherever the id does.
     */
    alias?: string | null;
    /**
     * Default sender, e.g. "Acme <orders@acme.com>". A send can override it.
     */
    from?: string | null;
    /**
     * Default subject. Can use variables. A send can override it.
     */
    subject?: string | null;
    /**
     * Default Reply-To address or addresses. A send can override it.
     */
    reply_to?: string | Array<string> | null;
    /**
     * The HTML body. Variables are written {{{KEY}}}, optionally with an inline fallback: {{{KEY|default}}}.
     */
    html?: string;
    /**
     * Plain-text body. When left out, the text part is generated from the HTML at send time. Exactly "" stops that, as in Resend; the email then carries an empty plain-text alternative.
     */
    text?: string | null;
    /**
     * Not in Resend. A Markdown body, rendered into SMTPfast's email layout. Used when html is empty.
     */
    markdown?: string | null;
    /**
     * Not in Resend. The inbox preview line, put into the email as a hidden first line.
     */
    preview_text?: string | null;
    /**
     * Not in Resend. A label for grouping templates in the dashboard.
     */
    category?: string | null;
    variables?: Array<TemplateVariableWritable>;
};

/**
 * Any field of CreateTemplateRequest. Only the fields sent change; variables, when sent, replace the whole list.
 */
export type UpdateTemplateRequestWritable = {
    name?: string;
    /**
     * A second handle, unique in the team, that works wherever the id does.
     */
    alias?: string | null;
    /**
     * Default sender, e.g. "Acme <orders@acme.com>". A send can override it.
     */
    from?: string | null;
    /**
     * Default subject. Can use variables. A send can override it.
     */
    subject?: string | null;
    /**
     * Default Reply-To address or addresses. A send can override it.
     */
    reply_to?: string | Array<string> | null;
    /**
     * The HTML body. Variables are written {{{KEY}}}, optionally with an inline fallback: {{{KEY|default}}}.
     */
    html?: string | null;
    /**
     * Plain-text body. When left out, the text part is generated from the HTML at send time. Exactly "" stops that, as in Resend; the email then carries an empty plain-text alternative.
     */
    text?: string | null;
    /**
     * Not in Resend. A Markdown body, rendered into SMTPfast's email layout. Used when html is empty.
     */
    markdown?: string | null;
    /**
     * Not in Resend. The inbox preview line, put into the email as a hidden first line.
     */
    preview_text?: string | null;
    /**
     * Not in Resend. A label for grouping templates in the dashboard.
     */
    category?: string | null;
    variables?: Array<TemplateVariableWritable> | null;
    /**
     * Not in Resend. The updated_at you loaded. If the template changed since, the update is refused with 409 revision_conflict instead of overwriting the newer version.
     */
    expected_updated_at?: string;
};

